import{_ as l,a0 as o,w as d,s as p,I as a,x as s,a1 as n,A as i,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"网络地址转换（NAT）之连接跟踪工具 | LCTT x X-CMD","titleTemplate":false,"description":"网络地址转换（NAT）之连接跟踪工具 | LCTT (202105) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"网络地址转换（NAT）之连接跟踪工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"网络地址转换（NAT）之连接跟踪工具 | LCTT (202105) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202105/20210212 Network address translation part 2 - the conntrack tool","title":"网络地址转换（NAT）之连接跟踪工具","tag":"202105","desc":""},"relativePath":"202105/20210212 Network address translation part 2 - the conntrack tool.md","filePath":"[post].md"}'),k={name:"202105/20210212 Network address translation part 2 - the conntrack tool.md"};function u(g,t,h,c,f,b){const e=o("Link");return d(),p("div",null,[t[35]||(t[35]=a("h1",{id:"网络地址转换-nat-之连接跟踪工具",tabindex:"-1"},[s("网络地址转换（NAT）之连接跟踪工具 "),a("a",{class:"header-anchor",href:"#网络地址转换-nat-之连接跟踪工具","aria-label":"Permalink to “网络地址转换（NAT）之连接跟踪工具”"},"​")],-1)),t[36]||(t[36]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202105/09/120958wwocez99o2nofw8s.jpg",alt:""})],-1)),a("p",null,[t[1]||(t[1]=s("这是有关",-1)),t[2]||(t[2]=a("ruby",null,[s("网络地址转换"),a("rt",null,"network address translation")],-1)),t[3]||(t[3]=s("（NAT）的系列文章中的第二篇。之前的第一篇文章介绍了 ",-1)),n(e,{href:"https://linux.cn/article-13364-1.html"},{default:i(()=>[...t[0]||(t[0]=[s("如何使用 iptables/nftables 的报文跟踪功能",-1)])]),_:1}),t[4]||(t[4]=s(" 来定位 NAT 相关的连接问题。作为第二部分，本文介绍 ",-1)),t[5]||(t[5]=a("code",null,"conntrack",-1)),t[6]||(t[6]=s(" 命令，它允许你查看和修改被跟踪的连接。",-1))]),t[37]||(t[37]=r(`<h3 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to “引言”">​</a></h3><p>通过 iptables 或 nftables 配置的 NAT 建立在 netfilters 连接跟踪子系统之上。<code>conntrack</code> 命令作为 “conntrack-tools” 软件包的一部分，用于查看和更改连接状态表。</p><h3 id="连接跟踪状态表" tabindex="-1">连接跟踪状态表 <a class="header-anchor" href="#连接跟踪状态表" aria-label="Permalink to “连接跟踪状态表”">​</a></h3><p>连接跟踪子系统会跟踪它看到的所有报文流。运行 <code>sudo conntrack -L</code> 可查看其内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tcp 6 43184 ESTABLISHED src=192.168.2.5 dst=10.25.39.80 sport=5646 dport=443 src=10.25.39.80 dst=192.168.2.5 sport=443 dport=5646 [ASSURED] mark=0 use=1</span></span>
<span class="line"><span>tcp 6 26 SYN_SENT src=192.168.2.5 dst=192.168.2.10 sport=35684 dport=443 [UNREPLIED] src=192.168.2.10 dst=192.168.2.5 sport=443 dport=35684 mark=0 use=1</span></span>
<span class="line"><span>udp 17 29 src=192.168.8.1 dst=239.255.255.250 sport=48169 dport=1900 [UNREPLIED] src=239.255.255.250 dst=192.168.8.1 sport=1900 dport=48169 mark=0 use=1</span></span></code></pre></div><p>上述显示结果中，每行表示一个连接跟踪项。你可能会注意到，每行相同的地址和端口号会出现两次，而且第二次出现的源地址/端口对和目标地址/端口对会与第一次正好相反！这是因为每个连接跟踪项会先后两次被插入连接状态表。第一个四元组（源地址、目标地址、源端口、目标端口）记录的是原始方向的连接信息，即发送者发送报文的方向。而第二个四元组则记录的是连接跟踪子系统期望收到的对端回复报文的连接信息。这解决了两个问题：</p><ol><li>如果报文匹配到一个 NAT 规则，例如 IP 地址伪装，相应的映射信息会记录在链接跟踪项的回复方向部分，并自动应用于同一条流的所有后续报文。</li><li>即使一条流经过了地址或端口的转换，也可以成功在连接状态表中查找到回复报文的四元组信息。</li></ol>`,7)),a("p",null,[t[8]||(t[8]=s("原始方向的（第一个显示的）四元组信息永远不会改变：它就是发送者发送的连接信息。NAT 操作只会修改回复方向（第二个）四元组，因为这是接受者看到的连接信息。修改第一个四元组没有意义：netfilter 无法控制发起者的连接状态，它只能在收到/转发报文时对其施加影响。当一个报文未映射到现有连接表项时，连接跟踪可以为其新建一个表项。对于 UDP 报文，该操作会自动进行。对于 TCP 报文，连接跟踪可以配置为只有 TCP 报文设置了 ",-1)),n(e,{href:"https://en.wikipedia.org/wiki/Transmission_Control_Protocol#TCP_segment_structure"},{default:i(()=>[...t[7]||(t[7]=[s("SYN 标志位",-1)])]),_:1}),t[9]||(t[9]=s(" 才新建表项。默认情况下，连接跟踪会允许从流的中间报文开始创建，这是为了避免对启用连接跟踪之前就存在的流处理出现问题。",-1))]),t[38]||(t[38]=r('<h3 id="连接跟踪状态表和-nat" tabindex="-1">连接跟踪状态表和 NAT <a class="header-anchor" href="#连接跟踪状态表和-nat" aria-label="Permalink to “连接跟踪状态表和 NAT”">​</a></h3><p>如上一节所述，回复方向的四元组包含 NAT 信息。你可以通过命令过滤输出经过源地址 NAT 或目标地址 NAT 的连接跟踪项。通过这种方式可以看到一个指定的流经过了哪种类型的 NAT 转换。例如，运行 <code>sudo conntrack -L -p tcp –src-nat</code> 可显示经过源 NAT 的连接跟踪项，输出结果类似于以下内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tcp 6 114 TIME_WAIT src=10.0.0.10 dst=10.8.2.12 sport=5536 dport=80 src=10.8.2.12 dst=192.168.1.2 sport=80 dport=5536 [ASSURED]</span></span></code></pre></div>',3)),a("p",null,[t[11]||(t[11]=s("这个连接跟踪项表示一条从 10.0.0.10:5536 到 10.8.2.12:80 的连接。与前面示例不同的是，回复方向的四元组不是原始方向四元组的简单翻转：源地址已修改。目标主机（10.8.2.12）将回复数据包发送到 192.168.1.2，而不是 10.0.0.10。每当 10.0.0.10 发送新的报文时，具有此连接跟踪项的路由器会将源地址替换为 192.168.1.2。当 10.8.2.12 发送回复报文时，该路由器将目的地址修改回 10.0.0.10。上述源 NAT 行为源自一条 ",-1)),n(e,{href:"https://wiki.nftables.org/wiki-nftables/index.php/Performing_Network_Address_Translation_(NAT)#Masquerading"},{default:i(()=>[...t[10]||(t[10]=[s("NFT 伪装",-1)])]),_:1}),t[12]||(t[12]=s(" 规则：",-1))]),t[39]||(t[39]=r(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>inet nat postrouting meta oifname &quot;veth0&quot; masquerade</span></span></code></pre></div><p>其他类型的 NAT 规则，例如目标地址 DNAT 规则或重定向规则，其连接跟踪项也会以类似的方式显示，回复方向四元组的远端地址或端口与原始方向四元组的远端地址或端口不同。</p><h3 id="连接跟踪扩展" tabindex="-1">连接跟踪扩展 <a class="header-anchor" href="#连接跟踪扩展" aria-label="Permalink to “连接跟踪扩展”">​</a></h3><p>连接跟踪的记帐功能和时间戳功能是两个有用的扩展功能。运行 <code>sudo sysctl net.netfilter.nf_conntrack_acct=1</code> 可以在运行 <code>sudo conntrack -L</code> 时显示每个流经过的字节数和报文数。运行 <code>sudo sysctl net.netfilter.nf_conntrack_timestamp=1</code> 为每个连接记录一个开始时间戳，之后每次运行 <code>sudo conntrack -L</code> 时都可以显示这个流从开始经过了多少秒。在上述命令中增加 <code>–output ktimestamp</code> 选项也可以看到流开始的绝对时间。</p><h3 id="插入和更改连接跟踪项" tabindex="-1">插入和更改连接跟踪项 <a class="header-anchor" href="#插入和更改连接跟踪项" aria-label="Permalink to “插入和更改连接跟踪项”">​</a></h3><p>你可以手动为状态表添加连接跟踪项，例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo conntrack -I -s 192.168.7.10 -d 10.1.1.1 --protonum 17 --timeout 120 --sport 12345 --dport 80</span></span></code></pre></div><p>这项命令通常被 conntrackd 用于状态复制，即将主防火墙的连接跟踪项复制到备用防火墙系统。于是当切换发生的时候，备用系统可以接管已经建立的连接且不会造成中断。连接跟踪还可以存储报文的带外元数据，例如连接跟踪标记和连接跟踪标签。可以用更新选项（<code>-U</code>）来修改它们：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo conntrack -U -m 42 -p tcp</span></span></code></pre></div><p>这条命令将所有的 TCP 流的连接跟踪标记修改为 42。</p><h3 id="删除连接跟踪项" tabindex="-1">删除连接跟踪项 <a class="header-anchor" href="#删除连接跟踪项" aria-label="Permalink to “删除连接跟踪项”">​</a></h3><p>在某些情况下，你可能想从状态表中删除条目。例如，对 NAT 规则的修改不会影响表中已存在流的经过报文。因此对 UDP 长连接（例如像 VXLAN 这样的隧道协议），删除表项可能很有意义，这样新的 NAT 转换规则才能生效。可以通过 <code>sudo conntrack -D</code> 命令附带可选的地址和端口列表选项，来删除相应的表项，如下例所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo conntrack -D -p udp  --src 10.0.12.4 --dst 10.0.0.1 --sport 1234 --dport 53</span></span></code></pre></div><h3 id="连接跟踪错误计数" tabindex="-1">连接跟踪错误计数 <a class="header-anchor" href="#连接跟踪错误计数" aria-label="Permalink to “连接跟踪错误计数”">​</a></h3><p><code>conntrack</code> 也可以输出统计数字：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># sudo conntrack -S</span></span>
<span class="line"><span>cpu=0 found=0 invalid=130 insert=0 insert_failed=0 drop=0 early_drop=0 error=0 search_restart=10</span></span>
<span class="line"><span>cpu=1 found=0 invalid=0 insert=0 insert_failed=0 drop=0 early_drop=0 error=0 search_restart=0</span></span>
<span class="line"><span>cpu=2 found=0 invalid=0 insert=0 insert_failed=0 drop=0 early_drop=0 error=0 search_restart=1</span></span>
<span class="line"><span>cpu=3 found=0 invalid=0 insert=0 insert_failed=0 drop=0 early_drop=0 error=0 search_restart=0</span></span></code></pre></div><p>大多数计数器将为 0。<code>Found</code> 和 <code>insert</code> 数将始终为 0，它们只是为了后向兼容。其他错误计数包括：</p><ul><li><code>invalid</code>：报文既不匹配已有连接跟踪项，也未创建新连接。</li><li><code>insert_failed</code>：报文新建了一个连接，但插入状态表时失败。这在 NAT 引擎在伪装时恰好选择了重复的源地址和端口时可能出现。</li><li><code>drop</code>：报文新建了一个连接，但是没有可用的内存为其分配新的状态条目。</li><li><code>early_drop</code>：连接跟踪表已满。为了接受新的连接，已有的未看到双向报文的连接被丢弃。</li><li><code>error</code>：icmp(v6) 收到与已知连接不匹配的 icmp 错误数据包。</li><li><code>search_restart</code>：查找过程由于另一个 CPU 的插入或删除操作而中断。</li><li><code>clash_resolve</code>：多个 CPU 试图插入相同的连接跟踪条目。</li></ul>`,18)),a("p",null,[t[14]||(t[14]=s("除非经常发生，这些错误条件通常无害。一些错误可以通过针对预期工作负载调整连接跟踪子系统的参数来降低其发生概率，典型的配置包括 ",-1)),t[15]||(t[15]=a("code",null,"net.netfilter.nf_conntrack_buckets",-1)),t[16]||(t[16]=s(" 和 ",-1)),t[17]||(t[17]=a("code",null,"net.netfilter.nf_conntrack_max",-1)),t[18]||(t[18]=s(" 参数。可在 ",-1)),n(e,{href:"https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/tree/Documentation/networking/nf_conntrack-sysctl.rst"},{default:i(()=>[...t[13]||(t[13]=[s("nf_conntrack-sysctl 文档",-1)])]),_:1}),t[19]||(t[19]=s(" 中查阅相应配置参数的完整列表。",-1))]),t[40]||(t[40]=r('<p>当报文状态是 <code>invalid</code> 时，请使用 <code>sudo sysctl net.netfilter.nf_conntrack_log_invalid=255</code> 来获取更多信息。例如，当连接跟踪遇到一个所有 TCP 标志位均为 0 的报文时，将记录以下内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nf_ct_proto_6: invalid tcp flag combination SRC=10.0.2.1 DST=10.0.96.7 LEN=1040 TOS=0x00 PREC=0x00 TTL=255 ID=0 PROTO=TCP SPT=5723 DPT=443 SEQ=1 ACK=0</span></span></code></pre></div><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>本文介绍了如何检查连接跟踪表和存储在跟踪流中的 NAT 信息。本系列的下一部分将延伸讨论连接跟踪工具和连接跟踪事件框架。</p><hr>',5)),a("p",null,[t[21]||(t[21]=s("via: ",-1)),n(e,{href:"https://fedoramagazine.org/network-address-translation-part-2-the-conntrack-tool/"},{default:i(()=>[...t[20]||(t[20]=[s("https://fedoramagazine.org/network-address-translation-part-2-the-conntrack-tool/",-1)])]),_:1})]),a("p",null,[t[26]||(t[26]=s("作者：",-1)),n(e,{href:"https://fedoramagazine.org/author/strlen/"},{default:i(()=>[...t[22]||(t[22]=[s("Florian Westphal",-1)])]),_:1}),t[27]||(t[27]=s(" 选题：",-1)),n(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...t[23]||(t[23]=[s("lujun9972",-1)])]),_:1}),t[28]||(t[28]=s(" 译者：",-1)),n(e,{href:"https://github.com/cooljelly"},{default:i(()=>[...t[24]||(t[24]=[s("cooljelly",-1)])]),_:1}),t[29]||(t[29]=s(" 校对：",-1)),n(e,{href:"https://github.com/wxy"},{default:i(()=>[...t[25]||(t[25]=[s("wxy",-1)])]),_:1})]),a("p",null,[t[32]||(t[32]=s("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[30]||(t[30]=[s("LCTT",-1)])]),_:1}),t[33]||(t[33]=s(" 原创编译，",-1)),n(e,{href:"https://linux.cn/"},{default:i(()=>[...t[31]||(t[31]=[s("Linux中国",-1)])]),_:1}),t[34]||(t[34]=s(" 荣誉推出",-1))])])}const N=l(k,[["render",u]]);export{C as __pageData,N as default};
